use serde_json::{json,Value};use std::{fs,io::{Read,Write,BufRead,BufReader},net::TcpListener,process::{Command,Stdio},os::unix::fs::PermissionsExt,sync::{Arc,Mutex,mpsc,atomic::{AtomicBool,Ordering}},thread,time::Duration};
#[test]
fn watch_routes_catalog_favorites_and_scroll_actions_without_waiting_for_poll(){
 let root=std::env::temp_dir().join(format!("t3-model-runtime-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let token=root.join("token");fs::write(&token,"synthetic-token").unwrap();fs::set_permissions(&token,fs::Permissions::from_mode(0o600)).unwrap();let exe=root.join("hyprctl");fs::write(&exe,"#!/bin/sh\nexit 1\n").unwrap();fs::set_permissions(&exe,fs::Permissions::from_mode(0o700)).unwrap();
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();listener.set_nonblocking(true).unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let config=root.join("env.json");fs::write(&config,json!({"environments":[{"id":"fixture","name":"Fixture","base_url":base,"token_file":token}]}).to_string()).unwrap();let stop=Arc::new(AtomicBool::new(false));let server_stop=stop.clone();let settings=Arc::new(Mutex::new(json!({"favorites":[],"sourceControlWritingStyle":{"mode":"repo_conventions","customInstructions":"Keep native instructions","followChangeRequestTemplates":true},"providerInstances":{"private":"fixture-do-not-export"}})));
 let inspected=settings.clone();
 let server=thread::spawn(move||while !server_stop.load(Ordering::Relaxed){if let Ok((mut s,_))=listener.accept(){let settings=settings.clone();thread::spawn(move||{s.set_read_timeout(Some(Duration::from_secs(2))).unwrap();let mut peek=[0;1024];let n=s.peek(&mut peek).unwrap_or(0);if String::from_utf8_lossy(&peek[..n]).starts_with("GET /ws"){let mut ws=tungstenite::accept(s).unwrap();let request:Value=serde_json::from_str(ws.read().unwrap().to_text().unwrap()).unwrap();let result=match request["tag"].as_str().unwrap(){"server.getConfig"=>json!({"providers":[{"instanceId":"work","driver":"codex","enabled":true,"displayName":"Work","status":"ready","models":[{"slug":"same","name":"Same"}]}],"settings":settings.lock().unwrap().clone()}),"server.getSettings"=>settings.lock().unwrap().clone(),"server.updateSettings"=>{let mut current=settings.lock().unwrap();if request["payload"]["patch"].get("setModelFavorites").is_some(){assert_eq!(request["payload"],json!({"patch":{"setModelFavorites":[{"provider":"work","model":"same","favorite":true}]}}));current["favorites"]=json!([{"provider":"work","model":"same"}]);}else{assert_eq!(request["payload"],json!({"patch":{"sourceControlWritingStyle":{"mode":"custom"}}}));current["sourceControlWritingStyle"]["mode"]=json!("custom");}current.clone()},_=>panic!("unexpected RPC")};ws.send(tungstenite::Message::Text(json!({"_tag":"Exit","requestId":"1","exit":{"_tag":"Success","value":result}}).to_string().into())).unwrap();}else{let mut bytes=[0;8192];let _=s.read(&mut bytes);let body=json!({"threads":[],"projects":[]}).to_string();write!(s,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",body.len(),body).unwrap();}});}else{thread::sleep(Duration::from_millis(5));}});
 let mut child=Command::new(env!("CARGO_BIN_EXE_omarchy-t3-client")).arg("watch").env("HOME",root.join("home")).env("T3CODE_HOME",root.join("native")).env("XDG_STATE_HOME",root.join("state")).env("PATH",format!("{}:{}",root.display(),std::env::var("PATH").unwrap())).env("OMARCHY_T3_FIXTURE_ENVIRONMENTS",config).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().unwrap();let mut input=child.stdin.take().unwrap();let output=child.stdout.take().unwrap();let (tx,rx)=mpsc::channel();thread::spawn(move||for line in BufReader::new(output).lines().map_while(Result::ok){if let Ok(v)=serde_json::from_str::<Value>(&line){let _=tx.send(v);}});
 for (op,id,expected) in [("catalog","first",0),("model-favorite","favorite",1),("catalog","second",1),("scroll-config","scroll",0)]{writeln!(input,"{}",json!({"op":op,"requestId":id,"environment":"fixture","provider":"work","model":"same","favorite":true})).unwrap();loop{let v=rx.recv_timeout(Duration::from_secs(3)).unwrap();if v["type"]=="action"&&v["data"]["requestId"]==id{let d=&v["data"];assert_eq!(d["op"],op);assert!(d["error"].is_null());if op=="scroll-config"{assert_eq!(d["result"]["mouseNative"],false);assert_eq!(d["result"]["touchpadNative"],false);}else{assert_eq!(d["result"]["favorites"].as_array().unwrap().len(),expected);}break}}}

 for (id,action,key,value) in [("settings-read","read","",Value::Null),("settings-write","update","sourceControlWritingStyle.mode",json!("custom")),("settings-reject","update","providerInstances",json!({}))] {
  writeln!(input,"{}",json!({"op":"settings","requestId":id,"environment":"fixture","action":action,"key":key,"value":value})).unwrap();
  loop {let v=rx.recv_timeout(Duration::from_secs(3)).unwrap();if v["type"]=="action"&&v["data"]["requestId"]==id {
   let d=&v["data"];assert_eq!(d["op"],"settings");
   if id=="settings-reject" {assert_eq!(d["error"],"invalid_settings");} else {
    assert!(d["error"].is_null(),"{d}");assert!(!d["result"].to_string().contains("fixture-do-not-export"));
    let mode=d["result"]["fields"].as_array().unwrap().iter().find(|f|f["key"]=="sourceControlWritingStyle.mode").unwrap();
    assert_eq!(mode["value"],if action=="read"{"repo_conventions"}else{"custom"});
   }break
  }}
 }
 {let raw=inspected.lock().unwrap();assert_eq!(raw["sourceControlWritingStyle"]["customInstructions"],"Keep native instructions");assert_eq!(raw["sourceControlWritingStyle"]["followChangeRequestTemplates"],true);assert_eq!(raw["favorites"].as_array().unwrap().len(),1);}
 writeln!(input,"{}",json!({"op":"quit"})).unwrap();child.wait().unwrap();stop.store(true,Ordering::Relaxed);server.join().unwrap();fs::remove_dir_all(root).unwrap();
}
